ssagier wordt vermoord, bevindt Hercule Poirot zich tussen een afgebakende groep mogelijke betrokkenen. Niemand lijkt de trein te hebben kunnen verlaten. Poirot onderzoekt verklaringen, alibi''s en onderlinge tegenstrijdigheden om te begrijpen wat er in de afgesloten wagons is gebeurd. De omstandigheden maken ieder detail belangrijk en iedere passagier mogelijk relevant.","work_id":977100047,"evidence":[{"url":"https://metadata.isbn.nl/369814/moord-in-de-orient-expres.html","fact":"Paperback ISBN 9789048822553 verschijningsdatum 15/09/2014 NUR 331 Detective imprint Pantheon uitgever Overamstel Uitgevers taal Nederlands","sha256":"9dceb221cc2065eea5485450c699a2886c582b1bbcef0fb3fd36c9dab0bf4d53","checkedAt":"2026-11-01T14:06:23.227Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Agatha Christie"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/369814/moord-in-de-orient-expres.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_author_id":928300045},"before_row":null},{"key":{"id":977200135},"seq":4,"relation":"editions","after_row":{"id":977200135,"title":"De Shining","isbn_10":null,"isbn_13":"9789021035437","work_id":977100048,"cover_id":null,"language":"nld","publisher":"Luitingh-Sijthoff B.V., Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200135},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100048,"evidence":[{"url":"https://metadata.isbn.nl/1571187/de-shining.html","fact":"Paperback ISBN 9789021035437 verschijningsdatum 21/09/2022 NUR 332 Thriller imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"111