bound_author_id":928300049},"before_row":null},{"key":{"work_id":977100049,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"Schrijver Paul Sheldon wordt op een afgelegen boerderij vastgehouden door Annie Wilkes, een bewonderaarster van zijn werk. Zij accepteert niet dat hij haar favoriete personage Misery heeft laten sterven. Terwijl Paul lichamelijk van haar afhankelijk is, dwingt Annie hem een ander vervolg te schrijven. Zijn beroep, dat eerst de reden voor zijn gevangenschap is, wordt ook een mogelijk middel om zich tegen haar controle te verzetten.","work_id":977100049,"evidence":[{"url":"https://metadata.isbn.nl/1571189/misery.html","fact":"Paperback ISBN 9789021035475 verschijningsdatum 21/09/2022 NUR 332 Thriller imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"c9a977820c8ee4a654fc7c30c17a223cc3d5b1a970848934c513df118a084050","checkedAt":"2026-11-01T14:06:29.637Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Stephen King"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1571189/misery.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_author_id":928300049},"before_row":null},{"key":{"id":977200137},"seq":10,"relation":"editions","after_row":{"id":977200137,"title":"Liefde in tijden van cholera","isbn_10":null,"isbn_13":"9789029090483","work_id":977100050,"cover_id":null,"language":"nld","publisher":"Meulenhoff Boekerij B.V.","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200137},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100050,"evidence":[{"url":"https://metadata.isb