r_id":977300026},"before_row":null},{"key":{"work_id":977100052,"language":"nl"},"seq":18,"relation":"catalog_work_descriptions","after_row":{"text":"Geneticus Don Tillman zoekt een levenspartner en probeert die zoektocht met een uitgebreide vragenlijst overzichtelijk te maken. Zijn plan werkt anders uit wanneer Rosie Jarman verschijnt, die niet aan zijn voorwaarden voldoet. Rosie zoekt haar biologische vader en kan Dons kennis gebruiken. Hun gezamenlijke onderzoek brengt hem in situaties die hij niet vooraf kan organiseren. Zo moet hij opnieuw nadenken over de eigenschappen die werkelijk van belang zijn in een relatie.","work_id":977100052,"evidence":[{"url":"https://metadata.isbn.nl/28744/het-rosie-project.html","fact":"Paperback ISBN 9789021024653 verschijningsdatum 16/01/2020 NUR 302 Vertaalde literaire roman, novelle imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"590e9801a0f069bf35472dee10312df4fa4e7d85d773a63fe5dfba8010edfe87","checkedAt":"2026-11-01T14:06:31.779Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Graeme Simsion"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/28744/het-rosie-project.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_author_id":977300026},"before_row":null},{"key":{"id":977200140},"seq":19,"relation":"editions","after_row":{"id":977200140,"title":"Zoen me tot ik zwicht","isbn_10":null,"isbn_13":"9789044360240","work_id":977100053,"cover_id":null,"language":"nld","publisher":"Overamstel Uitgevers","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200140},"seq":20,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100053,"evidence":[{"url":"https://metadata.isbn.nl/1093855/zoen-me-tot-ik-zwicht.html","fact":"Paperback ISBN 9789044360240 verschijningsdatum 11/05/2020 NUR 302 Vertaalde literaire roman, novelle imprint The House of Books uitgever Overamstel Uitgevers taal Nederlands","sha256":"98b6868d85dc69a9e363c921352fc6c2032ae63c90a7e0fa4ed81e8ad9e00a43","checkedAt":"2026-11-01T14:06:34.120Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Helen Hoang"},{"url":"https://metadata.isbn.nl/ie_fcache/0000344913_Zoen_me_tot_ik_zwicht_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet5","bytes":76516,"sha256":"1defe6758709a94e60a948ace949f705a9bd68798d7a03c7e28c4427c2a830d5","checkedAt":"2026-11-01T14:20:30.997Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000344913_Zoen_me_tot_ik_zwicht_0_0.jpg","edition_id":977200140,"bound_title":"Zoen me tot ik zwicht","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789044360240","evidence_url":"https://metadata.isbn.nl/1093855/zoen-me-tot-ik-zwicht.html","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":977300027},"before_row":null},{"key":{"work_id":977100053,"language":"nl"},"seq":21,"relation":"catalog_work_descriptions","after_row":{"text":"Stella kan uitstekend met wiskunde overweg, maar vindt sociale en intieme contacten moeilijk. Zij besluit haar beperkte ervaring op een praktische manier aan te pakken en vraagt escort Michael om hulp. Wat als een afgebakende oefening begint, roept gevoelens op die zich niet gemakkelijk laten berekenen. Stella moet ontdekken wat zij zelf verlangt wanneer afspraken en patronen minder houvast bieden dan haar belangstelling voor de persoon tegenover haar.","work_id":977100053,"evidence":[{"url":"https://metadata.isbn.nl/1093855/zoen-me-tot-ik-zwicht.html","fact":"Paperback ISBN 