01T14:20:32.294Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000083487_Het_achterhuis_0_0.jpg","edition_id":977200141,"bound_title":"Het achterhuis","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789044619287","evidence_url":"https://metadata.isbn.nl/216265/achterhuis.html","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":977300028},"before_row":null},{"key":{"work_id":977100054,"language":"nl"},"seq":24,"relation":"catalog_work_descriptions","after_row":{"text":"Anne Frank houdt tijdens de Duitse bezetting een dagboek bij in de vorm van brieven. Daarin probeert zij haar ervaringen en gedachten vast te leggen. Een radio-uitzending over het bewaren van getuigenissen brengt haar op het idee om haar teksten later als boek uit te geven. Haar dagboek verbindt de omstandigheden waarin zij leeft met een jonge, eigen stem die zich tot een denkbeeldige lezer richt.","work_id":977100054,"evidence":[{"url":"https://metadata.isbn.nl/216265/achterhuis.html","fact":"Hardback ISBN 9789044619287 verschijningsdatum 30/04/2014 NUR 321 Biografieen literaire auteurs uitgever Prometheus, Uitgeverij taal Nederlands","sha256":"bf7fd8604cc3cfe1938f7cc57619cc9c4db906bd942e07d9846e70870f86d046","checkedAt":"2026-11-01T14:02:46.114Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Anne Frank"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/216265/achterhuis.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_author_id":977300028},"before_row":null},{"key":{"id":977200142},"seq":25,"relation":"editions","after_row":{"id":977200142,"title":"Het onsterfelijke leven van Henriett