de ervaringen van haar familie bleven veel minder bekend. Rebecca Skloot brengt beide geschiedenissen samen. Het boek onderzoekt hoe wetenschappelijke vooruitgang, commerciële belangen en vragen over zeggenschap met elkaar botsen wanneer menselijk lichaamsmateriaal een zelfstandig bestaan in laboratoria krijgt.","work_id":977100055,"evidence":[{"url":"https://metadata.isbn.nl/994300/het-onsterfelijke-leven-van-henrietta-lacks.html","fact":"Paperback ISBN 9789046822982 verschijningsdatum 23/10/2017 NUR 686 Moderne geschiedenis (1870-heden) imprint Nieuw Amsterdam uitgever Park Uitgevers taal Nederlands","sha256":"ead2a43099f0f92141203eec4b21420ad40df7859dc5fa53d2d21d94ae64ee1f","checkedAt":"2026-11-01T14:02:48.479Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Rebecca Skloot"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/994300/het-onsterfelijke-leven-van-henrietta-lacks.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-06-20261101","review_status":"approved","bound_author_id":977300029},"before_row":null},{"key":{"id":977200143},"seq":28,"relation":"editions","after_row":{"id":977200143,"title":"Ons feilbare denken","isbn_10":null,"isbn_13":"9789047009009","work_id":977100056,"cover_id":null,"language":"nld","publisher":"Atlas Contact, Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200143},"seq":29,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100056,"evidence":[{"url":"https://metadata.isbn.nl/128673/ons-feilbare-denken.html","fact":"Paperback ISBN 9789047009009 verschijningsdatum 15/01/2016 NUR 770 Psychologie algemeen imprint Business Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","s