ijgen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://www.penguinrandomhouse.com/the-read-down/gabriel-garcia-marquez-books/","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/76260/liefde-in-tijden-van-cholera.html","sha256":"ff83b9b1925b8121c842925e841097b9559de8e31fc84b7b503c901a0de160e6","checkedAt":"2026-11-01T14:01:53.082Z","fact":"Paperback ISBN 9789029090483 verschijningsdatum 07/10/2014 NUR 300 Literaire fictie algemeen 302 Vertaalde literaire roman, novelle uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Gabriel Garcia Marquez","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://www.penguinrandomhouse.com/the-read-down/gabriel-garcia-marquez-books/","checkedAt":"2026-11-01","fact":"Work-bound content independently read; original factual summary, not source quotation."}]}},{"relation":"editions","ref":"edition:9789041411426","key":{"id":977200138},"before":null,"after":{"work_id":977100051,"title":"Noem me bij jouw naam","language":"nld","isbn_13":"9789041411426","isbn_10":null,"open_library_edition_id":null,"publisher":"Ambo/Anthos B.V.","id":977200138}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041411426","key":{"edition_id":"@edition:9789041411426"},"before":null,"after":{"edition_id":"@edition:9789041411426","work_id":977100051,"bound_author_id":977300025,"bound_title":"Noem me bij jouw naam","bound_language":"nld","bound_isbn13":"9789041411426","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000093003_Noem_me_bij_jouw_naam_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/401395/noem-me-bij-jouw-naam.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","r