 houvast bieden dan haar belangstelling voor de persoon tegenover haar.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1093855/zoen-me-tot-ik-zwicht.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/1093855/zoen-me-tot-ik-zwicht.html","sha256":"98b6868d85dc69a9e363c921352fc6c2032ae63c90a7e0fa4ed81e8ad9e00a43","checkedAt":"2026-11-01T14:06:34.120Z","fact":"Paperback ISBN 9789044360240 verschijningsdatum 11/05/2020 NUR 302 Vertaalde literaire roman, novelle imprint The House of Books uitgever Overamstel Uitgevers taal Nederlands","sourceAuthors":"Helen Hoang","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789044619287","key":{"id":977200141},"before":null,"after":{"work_id":977100054,"title":"Het achterhuis","language":"nld","isbn_13":"9789044619287","isbn_10":null,"open_library_edition_id":null,"publisher":"Prometheus, Uitgeverij","id":977200141}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044619287","key":{"edition_id":"@edition:9789044619287"},"before":null,"after":{"edition_id":"@edition:9789044619287","work_id":977100054,"bound_author_id":977300028,"bound_title":"Het achterhuis","bound_language":"nld","bound_isbn13":"9789044619287","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000083487_Het_achterhuis_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/216265/achterhuis.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/216265/achterhuis.html","sha256":"bf7fd8604cc3cfe1938f7cc57619cc9c4db906bd942e07d9846e70870f86d046","checkedAt":"2026-11