rengen haar in een wereld waarin sociale rechtvaardigheid en economische belangen met elkaar botsen. Tegelijk ontwikkelt zich een liefdesverhaal dat haar eigen opvattingen op de proef stelt. De roman verbindt haar persoonlijke ontwikkeling met vragen over de positie van vrouwen en de verhoudingen tussen mensen uit verschillende maatschappelijke groepen.","work_id":977100040,"evidence":[{"url":"https://metadata.isbn.nl/1473572/noord-en-zuid.html","fact":"Paperback ISBN 9789491618796 verschijningsdatum 17/08/2021 NUR 302 Vertaalde literaire roman, novelle imprint Astoria Uitgeverij uitgever Vrije Uitgevers, De taal Nederlands","sha256":"6732f16fdd26d6e1011f5f316eb077b9ce31726cc9dca71ccd9aeb12e733d63c","checkedAt":"2026-11-01T14:02:35.488Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Elizabeth Gaskell"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1473572/noord-en-zuid.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":977300020},"before_row":null},{"key":{"id":977200125},"seq":4,"relation":"editions","after_row":{"id":977200125,"title":"1984","isbn_10":null,"isbn_13":"9789403885797","work_id":977100041,"cover_id":null,"language":"nld","publisher":"Mijnbestseller B.V.","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200125},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100041,"evidence":[{"url":"https://metadata.isbn.nl/2090042/1984.html","fact":"Paperback ISBN 9789403885797 verschijningsdatum 15/04/2026 NUR 300 Literaire fictie algemeen imprint Veridan Books uitgever Mijnbestseller B.V. taal Nederlands","sha256":"8ff531d616697d271261696f6ca6b6d17c6a