id":929300014},"before_row":null},{"key":{"work_id":929100014,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"Victor Frankenstein slaagt erin om uit menselijke overblijfselen een levend wezen te scheppen. Wat voor hem een wetenschappelijke doorbraak moest zijn, roept angst en afschuw op. Zijn schepping ervaart hoe anderen hem afwijzen en zoekt erkenning bij de man die hem heeft gemaakt. Wanneer die verantwoordelijkheid steeds moeilijker te ontwijken wordt, raken maker en schepsel verwikkeld in een conflict over eenzaamheid, verlangens en de gevolgen van hun keuzes.","work_id":929100014,"evidence":[{"url":"https://metadata.isbn.nl/1443699/frankenstein.html","fact":"Paperback ISBN 9789463870191 verschijningsdatum 24/05/2021 NUR 315 Vertaalde pockets imprint Kemper Conseil Publishing uitgever Kemper Conseil Publishing Consultancy taal Nederlands","sha256":"f0bd8e1a12b1184272aafa537efb8de1e589058edc91b7b8722b1e5198c69ffe","checkedAt":"2026-11-01T14:05:57.078Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Mary Shelley"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1443699/frankenstein.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":929300014},"before_row":null},{"key":{"id":977200127},"seq":10,"relation":"editions","after_row":{"id":977200127,"title":"Heerlijke nieuwe wereld","isbn_10":null,"isbn_13":"9789029084932","work_id":977100042,"cover_id":null,"language":"nld","publisher":"Meulenhoff Boekerij B.V.","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200127},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100042