 hij niet aan wat anderen van zijn houding en verdediging verwachten. De roman stelt zijn persoonlijke manier van reageren tegenover de normen waarmee zijn omgeving hem beoordeelt. Zo gaat het niet alleen om een misdaad, maar ook om de vraag welke betekenis de samenleving aan iemands gedrag toekent.","work_id":977100045,"evidence":[{"url":"https://metadata.isbn.nl/135484/de-vreemdeling.html","fact":"Paperback ISBN 9789403149301 Nieuwe editie verschijningsdatum 16/09/2019 NUR 302 Vertaalde literaire roman, novelle uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sha256":"8f6eb4b4b168b9ad9d53b560c781ae8631ce5188a33436080511c30091895d6e","checkedAt":"2026-11-01T14:06:10.401Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Albert Camus"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/135484/de-vreemdeling.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":977300023},"before_row":null},{"key":{"id":977200133},"seq":28,"relation":"editions","after_row":{"id":977200133,"title":"De Da Vinci Code","isbn_10":null,"isbn_13":"9789024583416","work_id":977100046,"cover_id":null,"language":"nld","publisher":"Luitingh-Sijthoff B.V., Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200133},"seq":29,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100046,"evidence":[{"url":"https://metadata.isbn.nl/1411868/de-da-vinci-code.html","fact":"Paperback ISBN 9789024583416 verschijningsdatum 26/06/2018 NUR 332 Thriller imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"2f245729eb3d22079c7640982a59308cf43df839285ec42aa7ec76a