nce":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1411868/de-da-vinci-code.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":977300024},"before_row":null}],"batch":"nl006-reviewed-batch-05-20261101-test","project":"hlvujbrmfdlrfxdjwsmb"}'::jsonb::text,false);
