":"Exact ISBN block image + human visual title/author review, sheet4"}]}},{"relation":"catalog_work_descriptions","ref":"description:14","key":{"work_id":929100014,"language":"nl"},"before":null,"after":{"work_id":929100014,"language":"nl","bound_author_id":929300014,"text":"Victor Frankenstein slaagt erin om uit menselijke overblijfselen een levend wezen te scheppen. Wat voor hem een wetenschappelijke doorbraak moest zijn, roept angst en afschuw op. Zijn schepping ervaart hoe anderen hem afwijzen en zoekt erkenning bij de man die hem heeft gemaakt. Wanneer die verantwoordelijkheid steeds moeilijker te ontwijken wordt, raken maker en schepsel verwikkeld in een conflict over eenzaamheid, verlangens en de gevolgen van hun keuzes.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1443699/frankenstein.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/1443699/frankenstein.html","sha256":"f0bd8e1a12b1184272aafa537efb8de1e589058edc91b7b8722b1e5198c69ffe","checkedAt":"2026-11-01T14:05:57.078Z","fact":"Paperback ISBN 9789463870191 verschijningsdatum 24/05/2021 NUR 315 Vertaalde pockets imprint Kemper Conseil Publishing uitgever Kemper Conseil Publishing Consultancy taal Nederlands","sourceAuthors":"Mary Shelley","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789029084932","key":{"id":977200127},"before":null,"after":{"work_id":977100042,"title":"Heerlijke nieuwe wereld","language":"nld","isbn_13":"9789029084932","isbn_10":null,"open_library_edition_id":null,"publisher":"Meulenhoff Boekerij B.V.","id":977200127}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029084932","key":{"edition_id":"@edition:9789029084932