t de prijs van het georganiseerde geluk.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/311155/heerlijke-nieuwe-wereld.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/311155/heerlijke-nieuwe-wereld.html","sha256":"573eb8082b5df30e27e2d16253d2fac73bcb429df8324ba6ea94996d3e42155c","checkedAt":"2026-11-01T14:05:59.258Z","fact":"Paperback ISBN 9789029084932 verschijningsdatum 16/06/2009 NUR 340 Populaire fiction algemeen 302 Vertaalde literaire roman, novelle imprint J.M. Meulenhoff uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Aldous Huxley","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789022570838","key":{"id":977200128},"before":null,"after":{"work_id":921100019,"title":"Zenumagiër","language":"nld","isbn_13":"9789022570838","isbn_10":null,"open_library_edition_id":null,"publisher":"Meulenhoff Boekerij B.V.","id":977200128}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022570838","key":{"edition_id":"@edition:9789022570838"},"before":null,"after":{"edition_id":"@edition:9789022570838","work_id":921100019,"bound_author_id":921300015,"bound_title":"Zenumagiër","bound_language":"nld","bound_isbn13":"9789022570838","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000208982_Zenumagier_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/874137/zenumagier.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/874137/zenumagier.html","sha256":"9fcd971fa22f610657a1e5cfe1b9cd0f3a90f283c19eb274dec59a83eb573bc4","checkedAt":"2026-11-01T1