nguage":"nl"},"before":null,"after":{"work_id":977100045,"language":"nl","bound_author_id":977300023,"text":"Meursault doodt op klaarlichte dag een man en kan daar geen overtuigende verklaring voor geven. Tijdens het proces voldoet hij niet aan wat anderen van zijn houding en verdediging verwachten. De roman stelt zijn persoonlijke manier van reageren tegenover de normen waarmee zijn omgeving hem beoordeelt. Zo gaat het niet alleen om een misdaad, maar ook om de vraag welke betekenis de samenleving aan iemands gedrag toekent.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/135484/de-vreemdeling.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/135484/de-vreemdeling.html","sha256":"8f6eb4b4b168b9ad9d53b560c781ae8631ce5188a33436080511c30091895d6e","checkedAt":"2026-11-01T14:06:10.401Z","fact":"Paperback ISBN 9789403149301 Nieuwe editie verschijningsdatum 16/09/2019 NUR 302 Vertaalde literaire roman, novelle uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"Albert Camus","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789024583416","key":{"id":977200133},"before":null,"after":{"work_id":977100046,"title":"De Da Vinci Code","language":"nld","isbn_13":"9789024583416","isbn_10":null,"open_library_edition_id":null,"publisher":"Luitingh-Sijthoff B.V., Uitgeverij","id":977200133}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024583416","key":{"edition_id":"@edition:9789024583416"},"before":null,"after":{"edition_id":"@edition:9789024583416","work_id":977100046,"bound_author_id":977300024,"bound_title":"De Da Vinci Code","bound_language":"nld","bound_isbn13":"9789024583416","format":"pa