e Elliot liet zich jaren geleden overtuigen om de relatie met de man van wie zij hield te verbreken. Wanneer kapitein Frederick Wentworth opnieuw in haar omgeving verschijnt, komen oude gevoelens en twijfels terug. Anne moet zich verhouden tot de keuze die anderen mede voor haar bepaalden. Hun hernieuwde ontmoetingen draaien om spijt, maatschappelijke verwachtingen en de mogelijkheid om op een later moment alsnog een eigen beslissing te nemen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2059552/overreding-en-overtuiging.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/2059552/overreding-en-overtuiging.html","sha256":"c7012767093e8533cf1e91867516e612f4d5eefafc4aa8e157de302760c53603","checkedAt":"2026-11-01T14:02:31.079Z","fact":"Paperback ISBN 9789403866314 verschijningsdatum 28/05/2026 NUR 301 Literaire roman, novelle imprint Nordisk Menorah Press uitgever Mijnbestseller B.V. taal Nederlands","sourceAuthors":"Jane Austen","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789076542874","key":{"id":977200123},"before":null,"after":{"work_id":977100039,"title":"Verstand en gevoel","language":"nld","isbn_13":"9789076542874","isbn_10":null,"open_library_edition_id":null,"publisher":"Kemper Conseil Publishing Consultancy","id":977200123}},{"relation":"catalog_edition_metadata","ref":"metadata:9789076542874","key":{"edition_id":"@edition:9789076542874"},"before":null,"after":{"edition_id":"@edition:9789076542874","work_id":977100039,"bound_author_id":977300001,"bound_title":"Verstand en gevoel","bound_language":"nld","bound_isbn13":"9789076542874","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/00