erlangen dat geld niet kan oplossen. Zijn gevoelens voor Daisy Buchanan bepalen steeds sterker hoe hij naar zijn leven kijkt. Tegen de achtergrond van het Amerika van de jaren twintig onderzoekt de roman de afstand tussen uiterlijk succes en persoonlijke vervulling. Gatsby''s streven naar Daisy raakt verbonden met verwachtingen die moeilijk met de werkelijkheid te verzoenen zijn.","work_id":977100020,"evidence":[{"url":"https://metadata.isbn.nl/115111/de-grote-gatsby.html","fact":"Paperback ISBN 9789020417531 verschijningsdatum 30/05/2024 NUR 302 Vertaalde literaire roman, novelle imprint LJ Veen Klassiek uitgever Atlas Contact, Uitgeverij taal Nederlands","sha256":"b4f240cc9bb750d68bd11a617e0c56bb6c050c6cd286fc730219a005a6a3a0bf","checkedAt":"2026-11-01T13:59:44.231Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"F. Scott Fitzgerald , Francis Scott Fitzgerald"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/115111/de-grote-gatsby.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-03-20261101","review_status":"approved","bound_author_id":977300003},"before_row":null},{"key":{"id":977200105},"seq":4,"relation":"editions","after_row":{"id":977200105,"title":"American Gods","isbn_10":null,"isbn_13":"9789022568699","work_id":977100021,"cover_id":null,"language":"nld","publisher":"Meulenhoff Boekerij B.V.","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200105},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100021,"evidence":[{"url":"https://metadata.isbn.nl/11533/amerikaanse-goden.html","fact":"Paperback ISBN 9789022568699 verschijningsdatum 18/04/2017 NUR 334 Fantasy 302 Vertaalde literaire roman, novelle imprin