/metadata.isbn.nl/1238573/misdaad-en-straf.html","review_batch":"nl006-reviewed-batch-03-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":977300010},"before_row":null},{"key":{"work_id":977100027,"language":"nl"},"seq":24,"relation":"catalog_work_descriptions","after_row":{"text":"De arme student Raskolnikov zoekt in Sint-Petersburg een rechtvaardiging voor een roofmoord. Hij meent dat uitzonderlijke mensen zich niet aan dezelfde morele grenzen hoeven te houden als anderen. Zijn denkbeelden botsen echter met de gevolgen van zijn handelen en met zijn eigen geweten. De ontmoeting met Sonja brengt een andere kijk op verantwoordelijkheid en menselijkheid in zijn leven, terwijl de spanning rond de misdaad steeds verder toeneemt.","work_id":977100027,"evidence":[{"url":"https://metadata.isbn.nl/1238573/misdaad-en-straf.html","fact":"Hardback ISBN 9789028293168 verschijningsdatum 01/10/2019 NUR 302 Vertaalde literaire roman, novelle imprint Uitgeverij Van Oorschot uitgever Uitgeverij G.A. Van Oorschot B.V. taal Nederlands","sha256":"6b70f1d1a01af79e33f7564af38a1397d2a5dbbf1b4719b68d6e7955a02e539a","checkedAt":"2026-11-01T14:00:38.485Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"F Dostojevski"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1238573/misdaad-en-straf.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-03-20261101","review_status":"approved","bound_author_id":977300010},"before_row":null},{"key":{"id":977200112},"seq":25,"relation":"editions","after_row":{"id":977200112,"title":"Oorlog en vrede","isbn_10":null,"isbn_13":"9789028292086","work_id":977100028,"cover_id":null,"language":"nld","publisher":"Uitgeverij G.A. Van Oorschot B.V.","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200112},"seq":26,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100028,"evidence":[{"url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","fact":"Hardback ISBN 9789028292086 verschijningsdatum 10/05/2019 NUR 302 Vertaalde literaire roman, novelle imprint Uitgeverij Van Oorschot uitgever Uitgeverij G.A. Van Oorschot B.V. taal Nederlands","sha256":"5d6a09a80e09e7882fe7f6335e2e29a3fe000c67dbd79af0376b3d61b1cec8e2","checkedAt":"2026-11-01T14:00:40.630Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Leo Tolstoj , L.N. Tolstoj , Lev Tolstoj , Lev Nikolajevitsj Tolstoj , L N Tolstoj"},{"url":"https://metadata.isbn.nl/ie_fcache/0000526703_Oorlog_en_vrede_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet3","bytes":498976,"sha256":"32324318ed55c1ce1aae14b89c959789f3024095c91a4f4055fe060ab05981ec","checkedAt":"2026-11-01T14:19:54.156Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000526703_Oorlog_en_vrede_0_0.jpg","edition_id":977200112,"bound_title":"Oorlog en vrede","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789028292086","evidence_url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","review_batch":"nl006-reviewed-batch-03-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":977300011},"before_row":null},{"key":{"work_id":977100028,"language":"nl"},"seq":27,"relation":"catalog_work_descriptions","after_row":{"text":"Tegen de achtergrond van Napoleons oorlogen volgt de roman verschillende Russische adellijke families, waaronder de Rostovs en Bolkonski''s. Hun feesten, liefdes en persoonlijke beslissingen raken verbonden met gebeurtenissen die zij nauwelijks kunnen beheersen. Het verhaal beweegt tussen het intieme familieleven en de gevolgen van oorlog. Daarmee onderzoekt Tolstoj niet alleen menselijke verhoudingen, maar ook hoe geschiedenis ontstaat en hoeveel vrijheid een individu daarin werkelijk heeft.","work_id":977100028,"evidence":[{"url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","fact":"Hardback ISBN 9789028292086 verschijningsdatum 10/05/2019 NUR 302 Vertaalde literaire roman, novelle imprint Uitgeverij Van Oorschot uitgever Uitgeverij G.A. Van Oorschot B.V. taal Nederlands","sha256":"5d6a09a80e09e7882fe7f6335e2e29a3fe000c67dbd79af0376b3d61b1cec8e2","checkedAt":"2026-11-01T14:00:40.630Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Leo Tolstoj , L.N. Tolstoj , Lev Tolstoj , Lev Nikolajevitsj Tolstoj , L N Tolstoj"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-03-20261101","review_status":"approved","bound_author_id":977300011},"before_row":null},{"key":{"id":977200113},"seq":28,"relation":"editions","after_row":{"id":977200113,"title":"De oude man en de zee","isbn_10":null,"isbn_13":"9789025477974","work_id":977100029,"cover_id":null,"language":"nld","publisher":"Atlas Contact, Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200113},"seq":29,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100029,"evidence":[{"url":"https://metadata.isbn.nl/36836/de-oude-man-en-de-zee.html","fact":"Hardback ISBN 9789025477974 verschijningsdatum 04/11/2025 NUR 302 Vertaalde literaire roman, novelle imprint Atlas Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sha256":"038e81660fb498964df965ff2021b9e507d1ec0e91618e95bdb2421a4ea32736","checkedAt":"2026-11-01T14:00:47.293Z","ident