ingen waarin een eilandbestemming niet vanzelfsprekend rust of veiligheid biedt. Achter de vakantiesfeer schuilen geheimen en dreiging. Het boek brengt afzonderlijke verhalen samen; het is geen extra deel van één doorlopend verhaal. Ook een winnende inzending uit een vakantiethrillerwedstrijd is opgenomen.","work_id":977100016,"evidence":[{"url":"https://metadata.isbn.nl/1185010/de-eilanden.html","fact":"Paperback ISBN 9789400517813 verschijningsdatum 18/06/2024 NUR 332 Thriller imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sha256":"4d10e968e0d3a291626c5298a1e65b5ef24afa805f3c65e838d6c2a964444ea2","checkedAt":"2026-11-01T13:59:09.704Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Suzanne Vermeer"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1185010/de-eilanden.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-02-20261101","review_status":"approved","bound_author_id":91021002},"before_row":null},{"key":{"edition_id":977200032},"seq":13,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100017,"evidence":[{"url":"https://metadata.isbn.nl/2144054/fourth-wing-titel-volgt-niet-boek-4.html","fact":"Hardback ISBN 9789020564563 verschijningsdatum 29/09/2026 NUR 334 Fantasy imprint Z&K uitgever VBK Media taal Nederlands","sha256":"95605e63d7fb3e51b75ffe445454a045f5d4dae3dcf7169887b5a4b52e017dab","checkedAt":"2026-11-01T13:59:11.820Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Rebecca Yarros"},{"url":"https://metadata.isbn.nl/ie_fcache/0000799720_Threshing_day_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet2","bytes":902070,"s