gende oorlog haar plannen en gevoelens verder onder druk zet.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1399208/de-verbannen-koningin.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1399208/de-verbannen-koningin.html","sha256":"649b7ff79b81035fbfcd2012d747448b87be6f78b2488192af84c45a97a404e4","checkedAt":"2026-11-01T13:58:41.180Z","fact":"Hardback ISBN 9789022592847 verschijningsdatum 19/04/2021 NUR 334 Fantasy 285 Fictie 15+ imprint Boekerij uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Holly Black","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789463493666","key":{"edition_id":977200024},"before":null,"after":{"edition_id":977200024,"work_id":977100012,"bound_author_id":924300308,"bound_title":"De laatste zet","bound_language":"dut","bound_isbn13":"9789463493666","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000579489_De_laatste_zet_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1540816/de-laatste-zet.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1540816/de-laatste-zet.html","sha256":"49824d266fae9ac37c958853cdbc77d04217e17d2dd6b7fcac6e9e84f46a34d5","checkedAt":"2026-11-01T13:58:43.378Z","fact":"Hardback ISBN 9789463493666 verschijningsdatum 12/09/2022 NUR 285 Fictie 15+ imprint Blossom Books uitgever Blossom Books B.V. taal Nederlands","sourceAuthors":"Jennifer Lynn Barnes","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metada