  i:=i+1;select count(*) into n from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if n<>1 then raise exception 'Receipt manifest sequence mismatch';end if;
  select x into r from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if r->>'relation' is distinct from p->>'relation' then raise exception 'Receipt manifest relation mismatch';end if;
  k:=p->'key';expected:=p->'after';prior:=p->'before';
  for kv in select * from jsonb_each(expected) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Receipt manifest missing parent';end if;
    expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if prior<>'null'::jsonb then execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',p->>'relation') into prior using prior;end if;
  execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into expected using expected;
  if r->'key' is distinct from k or r->'before_row' is distinct from prior or jsonb_typeof(r->'after_row') is distinct from 'object' or not coalesce((r->'after_row')@>expected,false) then raise exception 'Receipt differs from exact reviewed manifest';end if;
  if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;
 end loop;
end;$manifest_guard$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl006-reviewed-batch-02-20261101-test' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>23 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;commit;

select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"edition_id":977200002},"seq":1,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100001,"evidence":[{"url":"https://metadata.isbn.nl/506805/val-der-titanen.html","fact":"Hardback ISBN 9789047514749 verschijningsdatum 01/10/2010 NUR 302 Vertaalde literaire roman, novelle imprint Van Holkema & Warendorf uitgever Meulenhoff Boekerij B.V. taal Nederlands","sha256":"f7fd470315a33e031df373097aaccd9696c8d1eecb7d975e81be4a3e0fda7724","checkedAt":"2026-11-01T13:14:28.838Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Ken Follett"},{"url":"https://metadata.isbn.nl/ie_fcache/0000119940_Val_der_titanen_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":89481,"sha256":"4ca10923ad667edfacd57e16224aae4f20d8de013ed81a5f643bb13abaa06ebc","checkedAt":"2026-11-01T13:16:55.496Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000119940_Val_der_titanen_0_0.jpg","edition_id":977200002,"bound_title":"Val der titanen","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789047514749","evidence_url":"https://metadata.isbn.nl/506805/val-der-titanen.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":928300358},"before_row":null},{"key":{"work_id":977100001,"language":"nl"},"seq":2,"relation":"catalog_work_descriptions","after_row":{"text":"Vanaf 1911 volgt deze roman mensen die hun toekomst proberen te bepalen terwijl de verhoudingen in de samenleving verschuiven. Arbeiders verzetten zich tegen onderdrukking, vrouwen eisen meer rechten en de aristocratie ziet haar vanzelfsprekende positie veranderen. Ondertussen beïnvloeden diplomatieke beslissingen het leven van mensen die daar nauwelijks zeggenschap over hebben. De aanloop naar de Eerste Wereldoorlog verbindt hun persoonlijke ambities met een veel grotere strijd om macht en verandering.","work_id":977100001,"evidence":[{"url":"https://metadata.isbn.nl/506805/val-der-titanen.html","fact":"Hardback ISBN 9789047514749 verschijningsdatum 01/10/2010 NUR 302 Vertaalde literaire roman, novelle imprint Van Holkema & Warendorf uitgever Meulenhoff Boekerij B.V. taal Nederlands","sha256":"f7fd470315a33e031df373097aaccd9696c8d1eecb7d975e81be4a3e0fda7724","checkedAt":"2026-11-01T13:14:28.838Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Ken Follett"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/506805/val-der-titanen.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":928300358},"before_row":null},{"key":{"edition_id":977200004},"seq":3,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100002,"evidence":[{"url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","fact":"Paperback ISBN 9789024564781 verschijningsdatum 17/09/2014 NUR 334 Fantasy uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"f9851ed6f66adc13f590013af4bdcf18e448556102f1aedf66e047cc23659d19","checkedAt":"2026-11-01T13:14:31.071Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Brandon Sanderson"},{"url":"https://metadata.isbn.nl/ie_fcache/0000059506_De_wet_van_staal_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":110625,"sha256":"1c8f3495f4321db7a0a829b7fa983d9172356fc499b648f68393ba53053803b2","checkedAt":"2026-11-01T13:16:57.521Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000059506_De_wet_van_staal_0_0.jpg","edition_id":977200004,"bound_title":"De wet van staal","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789024564781","evidence_url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":8800016},"before_row":null},{"key":{"work_id":977100002,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"Drie eeuwen na de oorspronkelijke verhalen over de Nevelmensen kent de wereld spoorwegen, elektrisch licht en een groeiend stadsleven. Toch zijn Ertsmagie en Ferrochemie niet verdwenen. Waxillium Ladrian heeft twintig jaar in de Ruigte doorgebracht en keert terug om zijn positie binnen een vooraanstaand Huis op zich te nemen. Zijn ervaring met wapens en magie staat tegenover de verwachtingen van een bestaan als edelman in een veranderde samenleving.","work_id":977100002,"evidence":[{"url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","fact":"Paperback ISBN 9789024564781 verschijningsdatum 17/09/2014 NUR 334 Fantasy uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"f9851ed6f66adc13f590013af4bdcf18e448556102f1aedf66e047cc23659d19","checkedAt":"2026-11-01T13:14:31.071Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Brandon Sanderson"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":8800016},"before_row":null},{"key":{"edition_id":977200006},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100003,"evidence":[{"url":"https://metadata.isbn.nl/1721715/things-we-hide-from-the-light.html","fact":"Paperback ISBN 9789020553703 verschijningsdatum 24/01/2024 NUR 302 Vertaalde literaire roman, novelle imprint Z&K uitgever VBK Media taal Nederlands","sha256":"cde51a5b98411ee15179903ed93ff61f2868cfde3f67a0685afe12d022ce13e2","checkedAt":"2026-11-01T13:14:33.185Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Lucy Score"},{"url":"https://metadata.isbn.nl/ie_fcache/0000539378_Things_we_hide_from_the_light_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":144825,"sha256":"26267691c0235336a06fdcefa1b282a0c592cbee01c3c92a72a67ef7b5287280","checkedAt":"2026-11-01T13:16:59.417Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000539378_Things_we_hide_from_the_light_0_0.jpg","edition_id":977200006,"bound_title":"Things We Hide from the Light","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789020553703","evidence_url":"https://metadata.isbn.nl/1721715/things-we-hide-from-the-light.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":924300399},"before_row":null},{"key":{"work_id":977100003,"language":"nl"},"seq":6,"relation":"catalog_work_descriptions","after_row":{"text":"Politiecommissaris Nash probeert te herstellen van een schietpartij. Zijn vertrouwde zelfverzekerdheid is aangetast door nachtmerries en paniekaanvallen, maar hij laat anderen nauwelijks merken hoe het met hem gaat. Buurvrouw Lina kijkt door die houding heen, hoewel ze niet van plan is lang in Knockemout te blijven. Wanneer ze op elkaar aangewezen raken, worden hun plannen ingewikkelder en moeten ze bepalen hoeveel ruimte ze de ander in hun leven willen geven.","work_id":977100003,"evidence":[{"url":"https://metadata.isbn.nl/1721715/things-we-hide-from-the-light.html","fact":"Paperback ISBN 9789020553703 verschijningsdatum 24/01/2024 NUR 302 Vertaalde literaire roman, novelle imprint Z&K uitgever VBK Media taal Nederlands","sha256":"cde51a5b98411ee15179903ed93ff61f2868cfde3f67a0685afe12d022ce13e2","checkedAt":"2026-11-01T13:14:33.185Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Lucy Score"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1721715/things-we-hide-from-the-light.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":924300399},"before_row":null},{"key":{"edition_id":977200008},"seq":7,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100004,"evidence":[{"url":"https://metadata.isbn.nl/1963438/king-of-sloth.html","fact":"Paperback ISBN 9789021498409 verschijningsdatum 10/07/2025 NUR 343 Romantiek imprint Love Books uitgever Singel Uitgeverijen taal Nederlands","sha256":"ef3dea621e837a093dbdf0b9e3fb49704df731e4097cfcee960310d606e988d9","checkedAt":"2026-11-01T13:15:07.779Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Ana Huang"},{"url":"https://metadata.isbn.nl/ie_fcache/0000717953_King_of_sloth_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":451988,"sha256":"5fdeaae11051090294523dd6f305fbc87e6522640dc949aa5afa2559bf7536a5","checkedAt":"2026-11-01T13:17:01.349Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000717953_King_of_sloth_0_0.jpg","edition_id":977200008,"bound_title":"King of Sloth","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789021498409","evidence_url":"https://metadata.isbn.nl/1963438/king-of-sloth.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":924300405},"before_row":null},{"key":{"work_id":977100004,"language":"nl"},"seq":8,"relation":"catalog_work_descriptions","after_row":{"text":"Xavier Castillo heeft geld, charme en weinig belangstelling voor de verwachtingen van zijn familie. Zijn pr-manager Sloane Kensington is juist ambitieus en laat zich niet gemakkelijk afleiden van haar werk. Zijn plagerijen maken hun samenwerking er niet eenvoudiger op. Wanneer Xaviers toekomst minder vanzelfsprekend wordt, verandert ook de betekenis van hun onderlinge contact. Sloane moet haar professionele grenzen bewaken tegenover iemand die gewend is zijn zin te krijgen.","work_id":977100004,"evidence":[{"url":"https://metadata.isbn.nl/1963438/king-of-sloth.html","fact":"Paperback ISBN 9789021498409 verschijningsdatum 10/07/2025 NUR 343 Romantiek imprint Love Books uitgever Singel Uitgeverijen taal Nederlands","sha256":"ef3dea621e837a093dbdf0b9e3fb49704df731e4097cfcee960310d606e988d9","checkedAt":"2026-11-01T13:15:07.779Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Ana Huang"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1963438/king-of-sloth.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":924300405},"before_row":null},{"key":{"edition_id":977200010},"seq":9,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100005,"evidence":[{"url":"https://metadata.isbn.nl/1762445/feilloos.html","fact":"Paperback ISBN 9789464820904 verschijningsdatum 01/03/2024 NUR 343 Romantiek imprint April Books uitgever April Books taal Nederlands","sha256":"e9813460312d4be051f2a32a3daad79798e2994376fa1681d5728bc72efa2ab8","checkedAt":"2026-11-01T13:15:09.976Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Elsie Silver"},{"url":"https://metadata.isbn.nl/ie_fcache/0000614500_Feilloos_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":167176,"sha256":"8a569911d335be67285602bd37ae9cd1db84d1a8b4e0f1164c1c1e78376feedd","checkedAt":"2026-11-01T13:17:03.296Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000614500_Feilloos_0_0.jpg","edition_id":977200010,"bound_title":"Feilloos","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789464820904","evidence_url":"https://metadata.isbn.nl/1762445/feilloos.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":975300002},"before_row":null},{"key":{"work_id":977100005,"language":"nl"},"seq":10,"relation":"catalog_work_descriptions","after_row":{"text":"Stierenrijder Rhett Eaton brengt met een ondoordachte uitspraak zijn sponsors in verlegenheid. Zijn agent wil verdere problemen voorkomen en stuurt dochter Summer met hem mee tijdens de laatste maanden van zijn tour. Summer wil laten zien dat ze haar werk aankan, terwijl Rhett weinig behoefte heeft aan toezicht. De voortdurende nabijheid maakt hun botsende verwachtingen persoonlijker en zet de grenzen tussen hun opdracht en hun gevoelens onder druk.","work_id":977100005,"evidence":[{"url":"https://metadata.isbn.nl/1762445/feilloos.html","fact":"Paperback ISBN 9789464820904 verschijningsdatum 01/03/2024 NUR 343 Romantiek imprint April Books uitgever April Books taal Nederlands","sha256":"e9813460312d4be051f2a32a3daad79798e2994376fa1681d5728bc72efa2ab8","checkedAt":"2026-11-01T13:15:09.976Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Elsie Silver"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1762445/feilloos.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":975300002},"before_row":null},{"key":{"edition_id":977200012},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100006,"evidence":[{"url":"https://metadata.isbn.nl/1423229/prins-caspian.html","fact":"Hardback ISBN 9789026610592 verschijningsdatum 01/01/2001 NUR 283 Fictie 10-12 jaar imprint Callenbach uitgever VBK Media taal Nederlands","sha256":"adda16c646268711aa1711ed2c74e8a4140a8f2415b81b415d83968c2b746039","checkedAt":"2026-11-01T13:15:12.174Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"C.S. Lewis , Chris Staples Lewis"},{"url":"https://metadata.isbn.nl/ie_fcache/0000127231_Prins_Caspian_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":108657,"sha256":"f654e1ac488d19189b3f6afa0093fbfc3cbfd4ce5591629fd2246fb76bccf331","checkedAt":"2026-11-01T13:17:05.192Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000127231_Prins_Caspian_0_0.jpg","edition_id":977200012,"bound_title":"Prins Caspian","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789026610592","evidence_url":"https://metadata.isbn.nl/1423229/prins-caspian.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":921300021},"before_row":null},{"key":{"work_id":977100006,"language":"nl"},"seq":12,"relation":"catalog_work_descriptions","after_row":{"text":"De vier kinderen Pevensie worden onverwacht teruggebracht naar Narnia, maar herkennen het land nauwelijks. Hun vroegere kasteel is vervallen en de sprekende dieren worden onderdrukt door koning Miraz. Van de dwerg Trumpkin horen ze wat er sinds hun vertrek is gebeurd. Prins Caspian zoekt steun om de heersende macht te weerstaan. De kinderen raken opnieuw betrokken bij een strijd om de toekomst van een wereld die zonder hen verder is gegaan.","work_id":977100006,"evidence":[{"url":"https://metadata.isbn.nl/1423229/prins-caspian.html","fact":"Hardback ISBN 9789026610592 verschijningsdatum 01/01/2001 NUR 283 Fictie 10-12 jaar imprint Callenbach uitgever VBK Media taal Nederlands","sha256":"adda16c646268711aa1711ed2c74e8a4140a8f2415b81b415d83968c2b746039","checkedAt":"2026-11-01T13:15:12.174Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"C.S. Lewis , Chris Staples Lewis"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1423229/prins-caspian.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":921300021},"before_row":null},{"key":{"edition_id":977200014},"seq":13,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100007,"evidence":[{"url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","fact":"Hardback ISBN 9789024558704 verschijningsdatum 22/11/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"59cd1e1afdb31305276b5c95c3e13c71fd966bb39f74566d287eefcb93fa1e11","checkedAt":"2026-11-01T13:15:14.357Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Robert Jordan"},{"url":"https://metadata.isbn.nl/ie_fcache/0000214261_Mes_van_dromen_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":87151,"sha256":"f0edc0ec82f317003a0e94ca4e658abef1feda2d3d9dd11205fd4c8dae60de66","checkedAt":"2026-11-01T13:17:07.093Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000214261_Mes_van_dromen_0_0.jpg","edition_id":977200014,"bound_title":"Mes van dromen","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789024558704","evidence_url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":8800015},"before_row":null},{"key":{"work_id":977100007,"language":"nl"},"seq":14,"relation":"catalog_work_descriptions","after_row":{"text":"De naderende Laatste Slag zet de landen en hoofdpersonen van Het Rad des Tijds steeds verder onder druk. Rhand Altor probeert zijn strijd tegen de Duistere te verenigen met de noodzaak een bestand met de Seanchanen te bereiken. Ondertussen volgen Perijn, Mart, Elayne en Egwene hun eigen gevaarlijke wegen. Militaire dreiging en interne verdeeldheid maken het moeilijk de krachten te verzamelen die voor de komende confrontatie nodig zijn.","work_id":977100007,"evidence":[{"url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","fact":"Hardback ISBN 9789024558704 verschijningsdatum 22/11/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"59cd1e1afdb31305276b5c95c3e13c71fd966bb39f74566d287eefcb93fa1e11","checkedAt":"2026-11-01T13:15:14.357Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Robert Jordan"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":8800015},"before_row":null},{"key":{"edition_id":977200016},"seq":15,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100008,"evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Robert Jordan , Brandon Sanderson"},{"url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":19791,"sha256":"cb0089408a0df111d238f4145be209a86c395efe2c805ad27c7866050b640635","checkedAt":"2026-11-01T13:17:08.991Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","edition_id":977200016,"bound_title":"Het Licht van Weleer","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789024594719","evidence_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":8800015},"before_row":null},{"key":{"work_id":977100008,"language":"nl"},"seq":16,"relation":"catalog_work_descriptions","after_row":{"text":"De vorsten van de grote naties verzamelen zich op de Akker van Merrilor, waar Rhand Altor hun steun nodig heeft voor de confrontatie met de Duistere. Zijn plannen roepen echter twijfel op, ook bij mensen die hem goed kennen. De mogelijkheid dat hij de zegels van de gevangenis van de Duistere verbreekt, verdeelt zijn medestanders. Dit afsluitende deel brengt de strijd om vertrouwen, samenwerking en het voortbestaan van de wereld samen.","work_id":977100008,"evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Robert Jordan , Brandon Sanderson"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":8800015},"before_row":null},{"key":{"edition_id":977200018},"seq":17,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100009,"evidence":[{"url":"https://metadata.isbn.nl/76895/het-boek-henry.html","fact":"Hardback ISBN 9789056724535 verschijningsdatum 04/09/2012 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sha256":"0bb7dc1c15a409a73e59f2f07b9bac87c004d53f412cd81cc56dacc027537efa","checkedAt":"2026-11-01T13:15:18.523Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Hilary Mantel"},{"url":"https://metadata.isbn.nl/ie_fcache/0000015478_Het_boek_Henry_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":87870,"sha256":"8aed96fe39b39ce299ef04abd9345ef42650a8fdc27248f4420ad5c6132b39d1","checkedAt":"2026-11-01T13:17:10.860Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000015478_Het_boek_Henry_0_0.jpg","edition_id":977200018,"bound_title":"Het boek Henry","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789056724535","evidence_url":"https://metadata.isbn.nl/76895/het-boek-henry.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":928301086},"before_row":null},{"key":{"work_id":977100009,"language":"nl"},"seq":18,"relation":"catalog_work_descriptions","after_row":{"text":"Thomas Cromwell probeert zijn positie aan het hof van Hendrik VIII te behouden terwijl het lot van Anne Boleyn steeds onzekerder wordt. Haar relatie met de koning raakt in een crisis en Cromwell krijgt opnieuw een beslissende rol in het uitvoeren van diens wensen. De roman volgt de korte periode van Annes neergang vanuit een machtswereld waarin persoonlijke belangen en politieke overleving voortdurend met elkaar verweven zijn.","work_id":977100009,"evidence":[{"url":"https://metadata.isbn.nl/76895/het-boek-henry.html","fact":"Hardback ISBN 9789056724535 verschijningsdatum 04/09/2012 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sha256":"0bb7dc1c15a409a73e59f2f07b9bac87c004d53f412cd81cc56dacc027537efa","checkedAt":"2026-11-01T13:15:18.523Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Hilary Mantel"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/76895/het-boek-henry.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":928301086},"before_row":null},{"key":{"edition_id":977200020},"seq":19,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":977100010,"evidence":[{"url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","fact":"Hardback ISBN 9789463492775 verschijningsdatum 07/09/2021 NUR 285 Fictie 15+ imprint Blossom Books uitgever Blossom Books B.V. taal Nederlands","sha256":"ac14ac5f72e2c198f4d088b1d61034912c9fca860ea7ad3d357e3a4067738a50","checkedAt":"2026-11-01T13:58:39.014Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Jennifer Lynn Barnes"},{"url":"https://metadata.isbn.nl/ie_fcache/0000566144_De_verloren_erfgenaam_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet1","bytes":788060,"sha256":"ac51401e2f6c0477410e811ba4454544732c8fb4bea126c45302ac8b86913e6c","checkedAt":"2026-11-01T14:19:28.758Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000566144_De_verloren_erfgenaam_0_0.jpg","edition_id":977200020,"bound_title":"De verloren erfgenaam","reviewed_at":"2026-11-01T14:24:00+00:00","bound_isbn13":"9789463492775","evidence_url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":924300308},"before_row":null},{"key":{"work_id":977100010,"language":"nl"},"seq":20,"relation":"catalog_work_descriptions","after_row":{"text":"Avery Grambs heeft onverwacht het vermogen van Tobias Hawthorne geërfd, maar weet nog altijd niet waarom hij juist haar koos. Met Jameson en Grayson om zich heen probeert zij te achterhalen hoe lang Hawthorne haar al in de gaten hield. De zoektocht maakt de familiegeschiedenis ingewikkelder in plaats van duidelijker. Terwijl Avery antwoorden zoekt, moet zij ook rekening houden met mensen die haar liever uit Hawthorne House zien verdwijnen.","work_id":977100010,"evidence":[{"url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","fact":"Hardback ISBN 9789463492775 verschijningsdatum 07/09/2021 NUR 285 Fictie 15+ imprint Blossom Books uitgever Blossom Books B.V. taal Nederlands","sha256":"ac14ac5f72e2c198f4d088b1d61034912c9fca860ea7ad3d357e3a4067738a50","checkedAt":"2026-11-01T13:58:39.014Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Jennifer Lynn Barnes"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-01-20261101","review_status":"approved","bound_author_id":924300308},"before_row":null}],"batch":"nl006-reviewed-batch-01-20261101-test","project":"hlvujbrmfdlrfxdjwsmb"}'::jsonb::text,false);
