do $manifest_guard$ declare reviewed jsonb:='[{"relation":"catalog_edition_metadata","ref":"metadata:9789047514749","key":{"edition_id":977200002},"before":null,"after":{"edition_id":977200002,"work_id":977100001,"bound_author_id":928300358,"bound_title":"Val der titanen","bound_language":"dut","bound_isbn13":"9789047514749","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000119940_Val_der_titanen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/506805/val-der-titanen.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/506805/val-der-titanen.html","sha256":"f7fd470315a33e031df373097aaccd9696c8d1eecb7d975e81be4a3e0fda7724","checkedAt":"2026-11-01T13:14:28.838Z","fact":"Hardback ISBN 9789047514749 verschijningsdatum 01/10/2010 NUR 302 Vertaalde literaire roman, novelle imprint Van Holkema & Warendorf uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Ken Follett","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000119940_Val_der_titanen_0_0.jpg","sha256":"4ca10923ad667edfacd57e16224aae4f20d8de013ed81a5f643bb13abaa06ebc","bytes":89481,"checkedAt":"2026-11-01T13:16:55.496Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:1425","key":{"work_id":977100001,"language":"nl"},"before":null,"after":{"work_id":977100001,"language":"nl","bound_author_id":928300358,"text":"Vanaf 1911 volgt deze roman mensen die hun toekomst proberen te bepalen terwijl de verhoudingen in de samenleving verschuiven. Arbeiders verzetten zich tegen onderdrukking, vrouwen eisen meer rechten en de aristocratie ziet haar vanzelfsprekende positie veranderen. Ondertussen beïnvloeden diplomatieke beslissingen het leven van mensen die daar nauwelijks zeggenschap over hebben. De aanloop naar de Eerste Wereldoorlog verbindt hun persoonlijke ambities met een veel grotere strijd om macht en verandering.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/506805/val-der-titanen.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/506805/val-der-titanen.html","sha256":"f7fd470315a33e031df373097aaccd9696c8d1eecb7d975e81be4a3e0fda7724","checkedAt":"2026-11-01T13:14:28.838Z","fact":"Hardback ISBN 9789047514749 verschijningsdatum 01/10/2010 NUR 302 Vertaalde literaire roman, novelle imprint Van Holkema & Warendorf uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Ken Follett","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024564781","key":{"edition_id":977200004},"before":null,"after":{"edition_id":977200004,"work_id":977100002,"bound_author_id":8800016,"bound_title":"De wet van staal","bound_language":"dut","bound_isbn13":"9789024564781","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000059506_De_wet_van_staal_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","sha256":"f9851ed6f66adc13f590013af4bdcf18e448556102f1aedf66e047cc23659d19","checkedAt":"2026-11-01T13:14:31.071Z","fact":"Paperback ISBN 9789024564781 verschijningsdatum 17/09/2014 NUR 334 Fantasy uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000059506_De_wet_van_staal_0_0.jpg","sha256":"1c8f3495f4321db7a0a829b7fa983d9172356fc499b648f68393ba53053803b2","bytes":110625,"checkedAt":"2026-11-01T13:16:57.521Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:1481","key":{"work_id":977100002,"language":"nl"},"before":null,"after":{"work_id":977100002,"language":"nl","bound_author_id":8800016,"text":"Drie eeuwen na de oorspronkelijke verhalen over de Nevelmensen kent de wereld spoorwegen, elektrisch licht en een groeiend stadsleven. Toch zijn Ertsmagie en Ferrochemie niet verdwenen. Waxillium Ladrian heeft twintig jaar in de Ruigte doorgebracht en keert terug om zijn positie binnen een vooraanstaand Huis op zich te nemen. Zijn ervaring met wapens en magie staat tegenover de verwachtingen van een bestaan als edelman in een veranderde samenleving.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/263584/de-wet-van-staal.html","sha256":"f9851ed6f66adc13f590013af4bdcf18e448556102f1aedf66e047cc23659d19","checkedAt":"2026-11-01T13:14:31.071Z","fact":"Paperback ISBN 9789024564781 verschijningsdatum 17/09/2014 NUR 334 Fantasy uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789020553703","key":{"edition_id":977200006},"before":null,"after":{"edition_id":977200006,"work_id":97710000