d to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024594719","key":{"edition_id":977200016},"before":null,"after":{"edition_id":977200016,"work_id":977100008,"bound_author_id":8800015,"bound_title":"Het Licht van Weleer","bound_language":"dut","bound_isbn13":"9789024594719","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan , Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","sha256":"cb0089408a0df111d238f4145be209a86c395efe2c805ad27c7866050b640635","bytes":19791,"checkedAt":"2026-11-01T13:17:08.991Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:2187","key":{"work_id":977100008,"language":"nl"},"before":null,"after":{"work_id":977100008,"language":"nl","bound_author_id":8800015,"text":"De vorsten van de grote naties verzamelen zich op de Akker van Merrilor, waar Rhand Altor hun steun nodig heeft voor de confrontatie met de Duistere. Zijn plannen roepen echter twijfel op, ook bij mensen die hem goed kennen. De mogelijkheid dat hij de zegels van de gevangenis van de Duistere verbreekt, verdeelt zijn medestanders. Dit afsluitende deel brengt de strijd om vertrouwen, samenwerking en het voortbestaan van de wereld samen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan , Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789056724535","key":{"edition_id":977200018},"before":null,"after":{"edition_id":977200018,"work_id":977100009,"bound_author_id":928301086,"bound_title":"Het boek Henry","bound_language":"dut","bound_isbn13":"9789056724535","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000015478_Het_boek_Henry_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/76895/het-boek-henry.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/76895/het-boek-henry.html","sha256":"0bb7dc1c15a409a73e59f2f07b9bac87c004d53f412cd81cc56dacc027537efa","checkedAt":"2026-11-01T13:15:18.523Z","fact":"Hardback ISBN 9789056724535 verschijningsdatum 04/09/2012 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sourceAuthors":"Hilary Mantel","identityNote":"Same canonical Work, translati